//! Byte-parity fixtures for the built-in DeepSeek-V4 encoder.
//!
//! `testdata/dsv4_thinking_cases.json` is generated by the ENGINE: every
//! `expected` comes from the real `encoding_dsv4.py`, fed the same
//! preprocessing `serving_chat.py` applies before it. Each case is emitted for
//! both reasoning-effort profiles, so neither side can silently assume one.
//! Regenerate with `gen_dsv4_thinking_cases.py` (see the router's copy of these
//! fixtures) whenever the engine encoder, its tool template, or the effort
//! prompts change.

use serde_json::Value;

use super::template_native::{EffortProfile, NativeEncoder};

/// One generated case. `thinking` and `reasoning_effort` are the request-side
/// inputs; `reasoning_effort_profile` is the checkpoint property this layer
/// resolves from the shipped encoder.
#[derive(serde::Deserialize)]
struct Case {
    name: String,
    messages: Vec<Value>,
    tools: Option<Value>,
    thinking: bool,
    reasoning_effort: Option<String>,
    reasoning_effort_profile: String,
    expected: String,
}

fn cases() -> Vec<Case> {
    let path = concat!(
        env!("CARGO_MANIFEST_DIR"),
        "/testdata/dsv4_thinking_cases.json"
    );
    let text = std::fs::read_to_string(path).expect("read dsv4 fixtures");
    serde_json::from_str(&text).expect("parse dsv4 fixtures")
}

fn encoder(profile: &str, thinking: bool) -> NativeEncoder {
    let effort_profile = match profile {
        "preview" => EffortProfile::Preview,
        "official" => EffortProfile::Official,
        other => panic!("unknown effort profile in fixtures: {other}"),
    };
    NativeEncoder::DeepSeekV4 {
        default_thinking: thinking,
        effort_profile,
    }
}

/// Every generated case must render byte for byte. A mismatch here means the
/// prompt this server sends differs from the one the Python entrypoint sends,
/// which shows up as wrong model behavior, not as an error.
#[test]
fn matches_engine_generated_prompts() {
    let mut failures = Vec::new();
    let all = cases();
    for case in &all {
        let rendered = encoder(&case.reasoning_effort_profile, case.thinking)
            .render(
                &case.messages,
                case.tools.as_ref(),
                None,
                case.reasoning_effort.as_deref(),
            )
            .unwrap_or_else(|error| panic!("{}: render failed: {error}", case.name));
        if rendered != case.expected {
            failures.push(format!(
                "{}\n  expected: {:?}\n  rendered: {:?}",
                case.name,
                truncate(&case.expected),
                truncate(&rendered),
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {} engine fixtures diverged:\n{}",
        failures.len(),
        all.len(),
        failures.join("\n")
    );
}

/// The divergence the profile axis exists for: the same request renders a
/// different preamble on each profile, so resolving it from the checkpoint is
/// not optional. Dynamo's encoder models only the preview ladder.
#[test]
fn profiles_disagree_on_the_same_request() {
    let messages = vec![serde_json::json!({"role": "user", "content": "ABCD"})];
    let render = |profile: &str| {
        encoder(profile, true)
            .render(&messages, None, None, Some("high"))
            .unwrap()
    };
    let preview = render("preview");
    let official = render("official");
    assert!(
        !preview.contains("Reasoning Effort:"),
        "preview `high` carries no preamble, got {preview:?}"
    );
    assert!(
        official.contains("Reasoning Effort: Absolute maximum"),
        "official `high` carries the max preamble, got {official:?}"
    );
}

/// An effort level the profile does not define is dropped rather than
/// approximated, matching `serving_chat.py`.
#[test]
fn unaccepted_effort_is_dropped() {
    let messages = vec![serde_json::json!({"role": "user", "content": "ABCD"})];
    let rendered = encoder("preview", true)
        .render(&messages, None, None, Some("medium"))
        .unwrap();
    assert!(
        !rendered.contains("Reasoning Effort:"),
        "`medium` is not a preview level, got {rendered:?}"
    );
}

/// Chat mode is the SGLang default, so a fresh encoder must not emit the
/// thinking-mode preamble even when the request asks for max effort. Dynamo's
/// own V4 formatter defaults the other way.
#[test]
fn chat_mode_emits_no_preamble() {
    let messages = vec![serde_json::json!({"role": "user", "content": "ABCD"})];
    let rendered = encoder("official", false)
        .render(&messages, None, None, Some("max"))
        .unwrap();
    assert_eq!(
        rendered,
        "<\u{ff5c}begin\u{2581}of\u{2581}sentence\u{ff5c}><\u{ff5c}User\u{ff5c}>ABCD<\u{ff5c}Assistant\u{ff5c}></think>"
    );
}

fn truncate(text: &str) -> String {
    let limit = 160;
    match text.char_indices().nth(limit) {
        Some((byte, _)) => format!("{}...", &text[..byte]),
        None => text.to_owned(),
    }
}
